WITH parsed AS (SELECT id, service, level, latency_ms, payload_json, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, CAST((status_code & 4) != 0 AS INT) AS is_flagged, context['region'] AS region, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['version'], 'unknown') AS version_or_default FROM app_logs) SELECT level, COUNT(*) AS event_count, SUM(CASE WHEN service = 'auth' THEN latency_ms ELSE 0 END) AS auth_latency_ms, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, BIT_OR(latency_ms) AS latency_ms_bit_or, SORT_ARRAY(COLLECT_SET(level)) AS level_list FROM parsed GROUP BY level;
